public static float getIndividualVisibility(DynamicHudElement element) {
    return DynamicHudController.getVisibility(element);
}

public static float getVisibility(DynamicHudElement element, HotbarType hotbarType, BarSlot slot) {
    if (DynamicHudController.shouldForceVisible() || HudDisplayRenderer.isRendering(HudDisplayRegistry.id(element, slot))) {
        return 1.0f;
    }
    return HudDisplayController.visibility(HudDisplayRegistry.id(element, slot));
}

private static boolean isTemperatureVisuallyAbnormal(LocalPlayer player) {
    if (AresHudCompatManager.isLsoLoaded) {
        return LsoCompat.isTemperatureVisuallyAbnormal((Player)player);
    }
    return AresHudCompatManager.isHomeostaticLoaded && HomeostaticCompat.isTemperatureVisuallyAbnormal((Player)player);
}

private static boolean shouldKeepTemperatureVisible(LocalPlayer player) {
    boolean animationHoldActive;
    boolean animationActive = AresHudCompatManager.isLsoLoaded && LsoCompat.isTemperatureAnimationActive((Player)player);
    boolean bl = animationHoldActive = lsoTemperatureAnimationHoldTicks > 0;
    if (animationActive) {
        lsoTemperatureAnimationHoldTicks = 24;
    } else if (animationHoldActive) {
        --lsoTemperatureAnimationHoldTicks;
    }
    return DynamicHudController.isTemperatureVisuallyAbnormal(player) || animationActive || animationHoldActive;
}

public static void beginCenterHudVisibilityCapture() {
    centerHudVisibility = 0.0f;
    capturingCenterHudVisibility = true;
}

public static void recordCenterHudVisibility(DynamicHudElement element, float visibility) {
    if (capturingCenterHudVisibility && element.group() == DynamicHudElement.Group.CENTER) {
        centerHudVisibility = Math.max(centerHudVisibility, visibility);
    }
}

public static void endCenterHudVisibilityCapture() {
    capturingCenterHudVisibility = false;
}

public static void reveal(DynamicHudElement element) {
    HudDisplayController.activity(element);
}

