public static void discover(int width, int height) {
    if (!active) {
        return;
    }
    if (AresHudCompatManager.isPeakStaminaLoaded) {
        PeakStaminaCompat.refreshEditorLayout(width, height);
    }
    for (ExternalHudManager.LayerInfo layer : ExternalHudManager.layers()) {
        if (ExternalHudEditor.excluded(layer.id, preset) || STATES.containsKey(layer.id)) continue;
        ExternalHudConfig.Entry saved = ExternalHudConfig.get(preset, layer.id.toString());
        ExternalHudConfig.Bounds recorded = ExternalHudCapture.snapshotBounds(layer.id);
        State state = new State(layer, ExternalHudEditor.copy(saved));
        if (recorded != null) {
            ExternalHudManager.updateBounds(state.entry, recorded, width, height);
        } else if (ExternalHudExamples.hasExample(layer.id)) {
            ExternalHudManager.updateBounds(state.entry, ExternalHudExamples.bounds(layer.id, width, height, 0), width, height);
        }
        if (state.entry.bounds == null) {
            state.entry.bounds = ExternalHudExamples.bounds(layer.id, width, height, STATES.size());
        }
        STATES.put(layer.id, state);
    }
}

public static boolean active() {
    return active;
}

