package com.super_awesome_baby.ares_hud.client.gui;

import com.super_awesome_baby.ares_hud.client.config.HudDisplaySettings;
import com.super_awesome_baby.ares_hud.client.gui.HudDisplaySignal;
import java.util.Arrays;

final class HudChangeThreshold {
    private HudDisplaySignal signal = new HudDisplaySignal();
    private double previousThreshold = Double.NaN;

    HudChangeThreshold() {
    }

    boolean matches(double[] values, double threshold, HudDisplaySettings.Condition condition) {
        if (Double.compare(this.previousThreshold, threshold) != 0) {
            this.signal = new HudDisplaySignal();
            this.previousThreshold = threshold;
        }
        this.signal.clearEvents();
        double[] thresholds = new double[values.length];
        Arrays.fill(thresholds, Math.max(1.0E-6, threshold * 0.999999));
        this.signal.sample(values, values, thresholds);
        return switch (condition) {
            case HudDisplaySettings.Condition.CHANGING -> this.signal.changed;
            case HudDisplaySettings.Condition.INCREASING -> this.signal.increased;
            case HudDisplaySettings.Condition.DECREASING -> this.signal.decreased;
            default -> false;
        };
    }
}

