package com.super_awesome_baby.ares_hud.client.gui.screen.config;

import net.minecraft.util.Mth;

final class CompactSidebarLayout {
    static final int ROW_HEIGHT = 24;

    CompactSidebarLayout() {
    }

    static int width(int screenWidth) {
        return Math.min(Math.max(96, screenWidth - 24), Mth.m_14045_((int)(screenWidth / 4), (int)152, (int)176));
    }

    static int contentTop(boolean layout, int screenHeight) {
        return layout ? 76 : (screenHeight < 300 ? 108 : 132);
    }

    static int contentBottom(int screenHeight) {
        return screenHeight - 64;
    }

    static int choiceTop(boolean layout, int screenHeight) {
        int top = CompactSidebarLayout.contentTop(layout, screenHeight);
        return top + (CompactSidebarLayout.contentBottom(screenHeight) - top >= 100 ? 52 : 26);
    }

    static int scrollLimit(int contentHeight, int top, int bottom) {
        return Math.max(0, contentHeight - Math.max(0, bottom - top));
    }

    static boolean rowVisible(int top, int height, int viewportTop, int viewportBottom) {
        return top >= viewportTop && top + height <= viewportBottom;
    }
}

